{
  "title": "Monthly Wildlife Strikes by State",
  "display_instruction": "How do seasons differ across **STATE**?",
  "input_tables": [
    "faa_wildlife_strikes"
  ],
  "code": "import pandas as pd\n\nmonth_order = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']\n\ndf = pd.read_parquet('data/faa_wildlife_strikes.parquet', columns=['INCIDENT_DATE', 'STATE'])\ndf = df.dropna(subset=['INCIDENT_DATE', 'STATE']).copy()\ndf['incident_date'] = pd.to_datetime(df['INCIDENT_DATE'], errors='coerce')\ndf = df.dropna(subset=['incident_date'])\ndf['month_num'] = df['incident_date'].dt.month\ndf['calendar_month'] = pd.Categorical(df['incident_date'].dt.strftime('%b'), categories=month_order, ordered=True)\n\nmonthly_state_strikes = (\n    df.groupby(['STATE', 'month_num', 'calendar_month'], as_index=False)\n      .size()\n      .rename(columns={'size': 'strike_count'})\n)\n\nstate_totals = monthly_state_strikes.groupby('STATE', as_index=False)['strike_count'].sum()\nstate_order = state_totals.sort_values('strike_count', ascending=False)['STATE']\nmonthly_state_strikes['STATE'] = pd.Categorical(monthly_state_strikes['STATE'], categories=state_order, ordered=True)\nmonthly_state_strikes = monthly_state_strikes.sort_values(['STATE', 'month_num'])\n",
  "output_variable": "monthly_state_strikes",
  "chart": {
    "chart_type": "Heatmap",
    "encodings": {
      "x": "calendar_month",
      "y": "STATE",
      "color": "strike_count"
    },
    "config": {
      "colorScheme": "viridis"
    }
  },
  "field_metadata": {
    "calendar_month": "Month",
    "STATE": "State",
    "strike_count": "Count"
  },
  "field_display_names": {
    "calendar_month": "Month",
    "STATE": "State",
    "strike_count": "Strikes"
  }
}
```

